(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.019-t*0.24)*16 + Math.sin(x*0.016+t*0.32)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+wx, sy = y+wy;
