  const wy2 = Math.cos(sy*0.022+t*0.38)*7 + Math.sin(sx*0.028-t*0.42)*4;
  const fx = sx+wx2, fy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.38)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.48)*105, 165+Math.sin(t*0.65)*55, 0.095, 1.75, 1.0],
    [240+Math.sin(t*0.28+2)*150, 115+Math.cos(t*0.45+1)*95, 0.055, 2.4, 0.6],
    [110+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.11, 1.55, 1.1],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.52)*85, 0.085, 1.95, 0.9],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.1, 1.6, 0.75],
    [420+Math.cos(t*0.42+2)*60, 190+Math.sin(t*0.48+4)*55, 0.08, 2.2, 0.85]
  ];
  let aS=0, iS=0, a2=0, i2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const d2 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.72+t*sp*0.55+1.6)*w;
    a2 += Math.sin(d2*f*1.3-t*sp*0.8+2.0)*w*0.5;
    i2 += Math.sin(d2*f*0.9+t*sp*0.7+0.8)*w*0.5;
  }
  const tw = 8;
  const act = (aS+a2)/(tw), inh = (iS+i2)/(tw);
  const bg1 = (Math.sin(fx*0.038+fy*0.022+t*0.75)+Math.sin(fx*0.028-fy*0.038+t*1.05))/2;
  const bg2 = Math.sin((fx+fy)*0.11+t*2.3)*0.25+Math.sin((fx-fy)*0.095-t*1.9)*0.25;
  const bg3 = Math.sin(fx*0.065+t*1.5)*Math.cos(fy*0.055-t*1.2)*0.15;
  const bg = bg1+bg2+bg3;
