  const sp2 = Math.sin(dist*0.08-ang*2+t*2.2)*0.15;
  const spiral = sp1+sp2;
  const cross = Math.sin(fx*0.12)*Math.sin(fy*0.12)+Math.sin((fx+fy)*0.085+t)*0.4+Math.sin((fx-fy)*0.07-t*0.8)*0.3;
  const cell = Math.tanh(cross*1.4)*0.28;
  const rd1 = Math.tanh((act-inh*0.65+bg*0.25+spiral)*2.0);
  const rd2 = Math.tanh((a2*0.7-i2*0.8-bg*0.2-spiral*0.5)*1.8);
  const rd = rd1*0.78+rd2*0.22;
  const blend = rd*0.72+cell*0.28;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,35,85],[12,65,115],[18,105,130],
    [30,155,145],[140,195,130],[220,200,75],
    [235,155,65],[225,95,65],[190,55,75],[120,30,65],
    [55,15,55],[25,10,48],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
